float paperHash(vec2 p) { return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453); }
vec3 toDisplay(vec3 c) {return mix(c*12.92,1.055*pow(max(c,vec3(0.)),vec3(1./2.4))-.055,step(vec3(.0031308),c));}
vec3 toLinear(vec3 c) { return mix(c/12.92,pow((c+.055)/1.055,vec3(2.4)),step(vec3(.04045),c)); }
vec3 plateSource(vec2 uv) {
 vec2 mirrored=1.-abs(mod(uv,2.)-1.);
 return toDisplay(vrchSampleSource0(mirrored).rgb);
}
float impression(vec3 c) {return 1.-dot(c,vec3(.2126,.7152,.0722));}
float screenInk(vec2 p,float coverage,float angle) {
 mat2 r=mat2(cos(angle),-sin(angle),sin(angle),cos(angle));
 vec2 cell=fract(r*p*uParam_density)-.5;
 float radius=sqrt(clamp(coverage,0.,1.))*.70;
 float aa=max(.012,uParam_density/min(iResolution.x,iResolution.y)*.7);
 return mix(coverage,1.-smoothstep(radius-aa,radius+aa,length(cell)),uParam_grain*.65);
}
void mainImage(out vec4 fragColor,in vec2 fragCoord) {
 vec2 uv=fragCoord/iResolution.xy;
 vec4 original=vrchSampleSource0(uv);
 vec2 ratio=vec2(min(iResolution.x,iResolution.y))/iResolution.xy;
 vec2 p=fragCoord/min(iResolution.x,iResolution.y);
 vec3 center=plateSource(uv);
 float ink=impression(center),gain=.88+uParam_pressure*.50;
 vec3 paper=vec3(.89,.82,.69),keyInk=vec3(.006,.015,.038);
 float push=max(smoothstep(.12,.70,uParam_accent),smoothstep(.025,.22,uParam_phrase));
 float drift=sin(vrchPhase_speed()*.45)*.004;
 float distance=uParam_registration+uParam_spread*(.12+.88*push)+drift;
 float angle=.07983+vrchPhase_turn();
 vec2 direction=vec2(cos(angle),sin(angle))*ratio;
 float warm=impression(plateSource(uv-direction*distance));
 float cold=impression(plateSource(uv+direction*distance*.72));
 // Three complete ink plates have fixed density. Only registration moves.
 float warmInk=screenInk(p,smoothstep(.08,.82,warm*gain),-.35);
 float coldInk=screenInk(p,smoothstep(.08,.82,cold*gain),.26);
 float mainInk=screenInk(p,smoothstep(.08,.76,ink*gain),.10);
 vec3 color=paper;
 color*=mix(vec3(1.),vec3(.025,.50,.55),coldInk*.64);
 color*=mix(vec3(1.),uParam_ink.rgb,warmInk*.62);
 color*=mix(vec3(1.),keyInk,mainInk*.70);
 color*=1.-(paperHash(floor(fragCoord))-.5)*uParam_grain*.08;
 fragColor=vec4(mix(original.rgb,toLinear(clamp(color,0.,1.)),uParam_amount),original.a);
}
